import { Component } from '@angular/core';
import { UsuarioService } from '../../services/usuario.service'
import { FormBuilder, FormGroup, NgForm, Validators } from '@angular/forms';
import { Usuario } from 'src/app/models/usuario';
import { LoginService } from '../../services/login.service';

@Component({
  selector: 'app-login',
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.css']
})
export class LoginComponent {
  public mostrarBtnIniciarSesion : boolean = false;
  public mostrarBtnRegistrar : boolean = false;
  public mostrarBtnCerrarSesion : boolean = true;
  public mostrarInicio : boolean = true;
  public mostrarRegistro : boolean  = true;
  public colorIconoUsuario : string = "black";
  public nombreUsuario : string = "Usuario sin identificar";
  public usuario : Usuario = new Usuario();

  public loginForm!: FormGroup;
  public haIniciado: boolean = false;

  constructor(public usuarioService: UsuarioService, 
    public formBuilder: FormBuilder,
    public loginService: LoginService){

  }

  ngOnInit(): void {
    this.loginForm = this.formBuilder.group({
      email:['', [Validators.required, Validators.email]],
      password:['', Validators.required]
    });
  }

  get fc(){
    return this.loginForm.controls;
  }


  //formulario
  limpiarForm(form?: NgForm){
    if(form){ //si existe el formulario lo vaciamos
      form.reset();
      this.usuarioService.usuarioSeleccionado = new Usuario(); // reseteamos el usuario
    }
  }

  agregarUsuario(form: NgForm){
    //form.value tiene los datos del usuario nuevo
    form.value.rol = 'Cliente';
    this.usuarioService.registrarUsuario(form.value)
      .subscribe( 
      (response: any) => { 
        alert('Usuario registrado Correctamente');
        this.limpiarForm(form);
      },
      (error) => {
        console.error("Error al registrar el usuario", error);
      });
  /*
    //rellenamos el usuario para poder hacer futuras compras
    this.usuario._id = this.usuarioService.usuarioSeleccionado._id;
    this.usuario.nombreCompleto = this.usuarioService.usuarioSeleccionado.nombreCompleto;
    this.usuario.direccion = this.usuarioService.usuarioSeleccionado.direccion;
    this.usuario.telefono = this.usuarioService.usuarioSeleccionado.telefono;
    this.usuario.email = this.usuarioService.usuarioSeleccionado.email;
    this.usuario.password = this.usuarioService.usuarioSeleccionado.password;
    this.usuario.rol = this.usuarioService.usuarioSeleccionado.rol;

    //funciones adicionales
      this.nombreUsuario = form.value.nombreCompleto;
      this.mostrarRegistro=true;
      this.mostrarBtnIniciarSesion = true;
      this.mostrarBtnRegistrar = true;
      this.mostrarBtnCerrarSesion = false;
      this.colorIconoUsuario = "#58d156"; //color verde
  }


  ocultarRegistro(){
    this.mostrarRegistro = true;
    this.mostrarInicio = false;
  }

  ocultarInicio(){
    this.mostrarRegistro=false;
    this.mostrarInicio = true;
  }

  enviar(){
    this.haIniciado = true;
    if(this.loginForm.invalid) return;
  
    //El interface define la forma que un objeto debe tener, incluyendo qué propiedades debe tener y sus tipos.
    interface RespuestaLogin {
      message: string;
      nombreCompleto?: string; // Asegúrate de que 'nombreCompleto' sea opcional si no siempre se devuelve
    }
    // Llama al servicio de autenticación para iniciar sesión
    this.usuarioService.iniciarSesion(this.loginForm.value)
    .subscribe(
      (response: any) => {
        // Si la solicitud es exitosa
        console.log('Inicio de sesión exitoso', response);
  
            //funciones adicionales
            if (response.nombreCompleto) {
              this.nombreUsuario = response.nombreCompleto;
            }
            this.mostrarInicio = true;
            this.mostrarBtnIniciarSesion = true;
            this.mostrarBtnRegistrar = true;
            this.mostrarBtnCerrarSesion = false;
            this.colorIconoUsuario = "#58d156"; //color verde
      },
      (error) => {
        // Manejo de errores en caso de fallo en el inicio de sesión
        console.error('Error al iniciar sesión', error);
        alert("Datos introducidos incorrectos, pruebe de otra forma");
      }
    );

  }

  cerrarSesion(){
    this.nombreUsuario = "Usuario sin identificar";  
    this.mostrarBtnIniciarSesion = false;
    this.mostrarBtnRegistrar = false;
    this.mostrarBtnCerrarSesion = true;
    this.colorIconoUsuario = "black";
    this.usuarioService.usuarioSeleccionado = new Usuario(); // reseteamos el usuario
    this.usuario = new Usuario();
  }
}
<div class="card">
    <div class="card-body d-flex align-items-center">
      <!-- Icono a la izquierda -->
      <div class="mb-3" style="margin-right: 5%; margin-top: 4%;">
       <span style="font-size: 30px;" [style.color]="colorIconoUsuario"><i class="bi bi-person-circle"></i></span>
      </div>
      <!-- Contenido (nombre) a la derecha -->
      <div>
        <h6 class="card-title" style="font-style: italic;color: gray;">{{nombreUsuario}}</h6>
      </div>
    </div>
</div>

<a href="#" class="btn btn-primary" (click)="ocultarRegistro()" [hidden]="mostrarBtnIniciarSesion" style="margin: 5%;">Iniciar Sesión</a>
<a href="#" class="btn btn-primary" (click)="ocultarInicio()" [hidden]="mostrarBtnRegistrar">Registrarse</a>
<a href="#" class="btn btn-primary" (click)="cerrarSesion()" [hidden]="mostrarBtnCerrarSesion" style="margin: 5%;">Cerrar sesión</a>

<!--LOGIN-->
<div [hidden]="mostrarInicio">
    <form class="card card-body" [formGroup]="loginForm" (ngSubmit)="enviar()">
        <div class="mb-3">
            <label class="form-label">Email:</label>
            <input type="email" class="form-control" placeholder="nombre@email.com" formControlName="email">
            <div class="errores" *ngIf="fc['email'].errors && haIniciado">
                <div *ngIf="fc['email'].errors['required']">No puede estar vacio</div>
                <div *ngIf="fc['email'].errors['email']">El email no es correcto</div>
            </div>
        </div>
        <div class="mb-3">
            <label class="form-label">Contraseña:</label>
            <input type="password" class="form-control" formControlName="password">
            <div class="errores" *ngIf="fc['password'].errors && haIniciado">
                <div *ngIf="fc['password'].errors['required']">No puede estar vacio</div>
                <div *ngIf="fc['password'].errors['password']">La contraseña no es correcto</div>
            </div>
        </div>
        <button type="submit" class="btn btn-primary">Enviar</button>
    </form> 
</div>

<!--REGISTRO-->
<div [hidden]="mostrarRegistro">
        <form class="card card-body" #usuarioForm="ngForm" (ngSubmit)="agregarUsuario(usuarioForm)"> <!--Hacemos un método que va a recoger todo los valores de los inputs-->
            <div class="mb-3">
                <label class="form-label">Nombre Completo:</label>
                <input type="text" class="form-control" name="nombreCompleto" #nombreCompleto="ngModel" [(ngModel)]="usuarioService.usuarioSeleccionado.nombreCompleto">
            </div> 
            <div class="mb-3">
                <label class="form-label">Dirección:</label>
                <input type="text" class="form-control"  name="direccion"  #direccion="ngModel" [(ngModel)]="usuarioService.usuarioSeleccionado.direccion">
            </div> 
            <div class="mb-3">
                <label class="form-label">Telefono:</label>
                <input type="tlf" class="form-control" name="telefono" #telefono="ngModel" [(ngModel)]="usuarioService.usuarioSeleccionado.telefono">
            </div>
            <div class="mb-3">
                <label class="form-label">Email:</label>
                <input type="email" class="form-control" placeholder="nombre@email.com" name="email" #email="ngModel" [(ngModel)]="usuarioService.usuarioSeleccionado.email">
            </div>
            <div class="mb-3">
                <label class="form-label">Contraseña:</label>
                <input type="password" class="form-control" name="password" #password="ngModel" [(ngModel)]="usuarioService.usuarioSeleccionado.password">
            </div>
            <input type="button" class="btn btn-primary" style="margin: 3%;" (click)="agregarUsuario(usuarioForm)"  value="Registrar">    
            <input type="button" class="btn btn-primary" style="margin: 3%;" (click)="limpiarForm(usuarioForm)" value="Limpiar">   
        </form>
</div>
